using System;
using UnityEngine;

namespace LittleBuildersWorld.Guide
{
    /// <summary>
    /// Everything the helper can say: one entry per key with the bubble text and the voice clip for each language.
    /// Generated by the setup pipeline from Tools/voice/voice_lines.json (the single source for words and audio).
    /// </summary>
    [CreateAssetMenu(menuName = "Little Builders World/Guide Library", fileName = "GuideLibrary")]
    public sealed class GuideLibrary : ScriptableObject
    {
        [Serializable]
        public sealed class Line
        {
            public string key;
            public string en;
            public string th;
            public AudioClip voiceEn;
            public AudioClip voiceTh;
        }

        public Line[] lines = Array.Empty<Line>();

        public Line Find(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            for (int i = 0; i < lines.Length; i++)
            {
                if (lines[i] != null && lines[i].key == key) return lines[i];
            }
            return null;
        }

        public bool Has(string key) => Find(key) != null;

        /// <summary>Text and clip in the requested language; falls back to English when a translation is missing.</summary>
        public bool TryGet(string key, string language, out string text, out AudioClip voice)
        {
            Line l = Find(key);
            text = null;
            voice = null;
            if (l == null) return false;
            bool thai = language == Language.Thai && !string.IsNullOrEmpty(l.th);
            text = thai ? ThaiText.PlaceMarks(l.th) : l.en;
            voice = thai ? l.voiceTh : l.voiceEn;
            return !string.IsNullOrEmpty(text);
        }
    }

    /// <summary>
    /// TextMeshPro draws Thai without OpenType mark positioning, so a tone mark after an upper vowel (ที่) lands on
    /// top of the vowel, and marks over tall consonants (ป ฝ ฟ ฬ) hit the consonant's stem. This adds TMP rich-text
    /// offsets that do what the font's positioning table would: lift stacked tone marks, nudge marks left over tall
    /// consonants. Measured on Mitr (1000 units/em: marks sit at 602–844, tall stems reach x 581/633).
    /// </summary>
    public static class ThaiText
    {
        private const string Lift = "<voffset=0.24em>";
        private const string LiftEnd = "</voffset>";
        private const string Left = "<space=-0.15em>";
        private const string LeftEnd = "<space=0.15em>";

        public static bool IsConsonant(char c) => c >= 'ก' && c <= 'ฮ';
        public static bool IsUpperVowel(char c) => c == 'ั' || (c >= 'ิ' && c <= 'ื') || c == '็' || c == 'ํ';
        public static bool IsToneMark(char c) => c >= '่' && c <= '์';
        public static bool IsLowerVowel(char c) => c >= 'ุ' && c <= 'ฺ';
        public static bool IsTall(char c) => c == 'ป' || c == 'ฝ' || c == 'ฟ' || c == 'ฬ';

        public static string PlaceMarks(string s)
        {
            if (string.IsNullOrEmpty(s)) return s;
            var sb = new System.Text.StringBuilder(s.Length + 16);
            char baseChar = '\0';
            bool upperVowelOnBase = false;
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                bool upper = IsUpperVowel(c);
                bool tone = IsToneMark(c);
                if (!upper && !tone)
                {
                    if (IsConsonant(c)) { baseChar = c; upperVowelOnBase = false; }
                    else if (!IsLowerVowel(c)) { baseChar = '\0'; upperVowelOnBase = false; }
                    sb.Append(c);
                    continue;
                }
                bool raise = tone && (upperVowelOnBase || (i + 1 < s.Length && s[i + 1] == 'ำ'));
                bool left = IsTall(baseChar);
                if (left) sb.Append(Left);
                if (raise) sb.Append(Lift).Append(c).Append(LiftEnd);
                else sb.Append(c);
                if (left) sb.Append(LeftEnd);
                if (upper) upperVowelOnBase = true;
            }
            return sb.ToString();
        }
    }

    /// <summary>The helper's language: the saved choice, or the device language when none was chosen.</summary>
    public static class Language
    {
        public const string English = "en";
        public const string Thai = "th";

        public static string Resolve(string saved, SystemLanguage device)
        {
            if (saved == English || saved == Thai) return saved;
            return device == SystemLanguage.Thai ? Thai : English;
        }

        public static string Current
        {
            get
            {
                var s = Core.GameServices.Instance;
                return Resolve(s != null ? s.Save.Data.language : "", Application.systemLanguage);
            }
        }
    }
}
